import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronDown } from 'lucide-react';

const WORDS = ["Businesses", "Startups", "NGOs", "Organizations", "Institutions", "Schools", "Colleges", "MSMEs"];

const Hero: React.FC = () => {
  const [index, setIndex] = useState(0);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;

    let particles: {x: number, y: number, vx: number, vy: number}[] = [];
    const particleCount = Math.min(Math.floor((width * height) / 20000), 60);

    for(let i=0; i<particleCount; i++) {
      particles.push({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * 0.2,
        vy: (Math.random() - 0.5) * 0.2
      });
    }

    let animationId: number;
    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      // Purple/Blue particles
      ctx.strokeStyle = 'rgba(79, 70, 229, 0.08)'; 
      ctx.fillStyle = 'rgba(147, 51, 234, 0.08)'; 

      for(let i=0; i<particles.length; i++) {
        let p = particles[i];
        p.x += p.vx;
        p.y += p.vy;

        if(p.x < 0 || p.x > width) p.vx *= -1;
        if(p.y < 0 || p.y > height) p.vy *= -1;

        ctx.beginPath();
        ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
        ctx.fill();

        for(let j=i+1; j<particles.length; j++) {
          let p2 = particles[j];
          let dx = p.x - p2.x;
          let dy = p.y - p2.y;
          let dist = Math.sqrt(dx*dx + dy*dy);

          if(dist < 150) {
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
          }
        }
      }
      animationId = requestAnimationFrame(animate);
    };

    animate();

    const handleResize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setIndex((prevIndex) => (prevIndex + 1) % WORDS.length);
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  const handleScrollDown = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    const element = document.getElementById('about');
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section id="home" className="relative w-full min-h-screen flex items-center overflow-hidden bg-white">
      {/* Dynamic Background Gradients */}
      <div className="absolute inset-0 z-0 overflow-hidden">
        <div className="absolute top-0 -left-[10%] w-[50%] h-[50%] bg-purple-200/40 rounded-full blur-[100px] animate-blob"></div>
        <div className="absolute top-[20%] right-0 w-[50%] h-[50%] bg-indigo-200/40 rounded-full blur-[100px] animate-blob animation-delay-2000"></div>
        <div className="absolute -bottom-[20%] left-[20%] w-[60%] h-[60%] bg-blue-200/40 rounded-full blur-[100px] animate-blob animation-delay-4000"></div>
      </div>

      {/* Canvas Layer */}
      <canvas 
        ref={canvasRef} 
        className="absolute inset-0 z-10 pointer-events-none"
      />

      {/* Content */}
      <div className="relative z-20 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-32 flex flex-col justify-center h-full">
        <motion.div 
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="w-full max-w-4xl"
        >
          <div className="inline-block px-4 py-1.5 rounded-full bg-indigo-50 border border-indigo-100 mb-6">
            <span className="bg-gradient-to-r from-secondary to-purple text-transparent bg-clip-text font-bold text-sm tracking-wide uppercase">
              Leading Digital Innovation
            </span>
          </div>

          <h1 className="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-extrabold leading-tight mb-8 text-primary tracking-tight">
            <span className="block mb-2">
              <span className="text-slate-900">Empowering Indian</span>
            </span>

            {/* Changing Word Section with Gradient */}
            <span className="block h-[1.3em] sm:h-[1.2em] overflow-hidden my-2">
               <AnimatePresence mode="wait">
                  <motion.span
                    key={WORDS[index]}
                    initial={{ y: 50, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    exit={{ y: -50, opacity: 0 }}
                    transition={{ duration: 0.4, ease: "easeOut" }}
                    className="block bg-gradient-to-r from-secondary via-purple to-indigo-600 text-transparent bg-clip-text pb-2"
                  >
                    {WORDS[index]}
                  </motion.span>
                </AnimatePresence>
            </span>

            <motion.span 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.9, duration: 0.6 }}
              className="block mt-2 sm:mt-4 text-2xl sm:text-4xl md:text-5xl font-semibold leading-tight text-slate-600"
            >
              with Digital & Automation Solutions
            </motion.span>
          </h1>

          <motion.p 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1.1, duration: 0.8 }}
            className="text-lg sm:text-xl text-slate-600 mb-10 max-w-2xl leading-relaxed font-light"
          >
            We blend <span className="font-medium text-indigo-600">Strategy</span>, <span className="font-medium text-purple-600">Design</span>, and <span className="font-medium text-blue-600">Technology</span> to build digital experiences that drive real business growth.
          </motion.p>

          <motion.div
             initial={{ opacity: 0, y: 20 }}
