      >
        <span className="text-slate-400 text-[10px] font-bold tracking-[0.2em] uppercase group-hover:text-secondary transition-colors">Scroll</span>
        <motion.div
          animate={{ y: [0, 8, 0] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
          className="p-2 rounded-full border border-slate-200 group-hover:border-secondary/50 group-hover:bg-indigo-50 transition-colors"
        >
          <ChevronDown className="h-5 w-5 text-slate-400 group-hover:text-secondary transition-colors" />
        </motion.div>
      </motion.a>
    </section>
  );
};

