const TiltCard: React.FC<{ service: typeof SERVICES[0] }> = ({ service }) => {
  const ref = useRef<HTMLDivElement>(null);
  const [rotateX, setRotateX] = useState(0);
  const [rotateY, setRotateY] = useState(0);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    const rotateXValue = ((y - centerY) / centerY) * -10; // Max 10 deg
    const rotateYValue = ((x - centerX) / centerX) * 10; // Max 10 deg

    setRotateX(rotateXValue);
    setRotateY(rotateYValue);
  };

  const handleMouseLeave = () => {
    setRotateX(0);
    setRotateY(0);
  };

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        transformStyle: "preserve-3d",
        transform: `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
      }}
      className="bg-white rounded-2xl p-8 shadow-3d border border-white cursor-pointer transition-transform duration-100 ease-linear"
    >
      <div 
        style={{ transform: "translateZ(30px)" }}
        className="w-16 h-16 rounded-xl bg-gradient-to-br from-indigo-50 to-white shadow-inner mb-6 flex items-center justify-center border border-slate-100"
      >
        <service.icon className="h-8 w-8 text-secondary drop-shadow-md" />
      </div>

      <h3 
        style={{ transform: "translateZ(20px)" }}
        className="text-2xl font-bold text-slate-900 mb-4"
      >
        {service.title}
      </h3>

      <p 
        style={{ transform: "translateZ(10px)" }}
        className="text-slate-600 leading-relaxed"
      >
        {service.description}
      </p>

      {/* Glossy Overlay */}
      <div className="absolute inset-0 rounded-2xl bg-gradient-to-br from-white/40 to-transparent pointer-events-none mix-blend-overlay"></div>
    </motion.div>
  );
};

