          <div className="lg:w-7/12 p-10 bg-white">
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-700 ml-1">Full Name</label>
                  <input
                    type="text"
                    name="name"
                    required
                    value={formData.name}
                    onChange={handleChange}
                    className="w-full px-4 py-3 rounded-xl bg-slate-50 shadow-inner-3d border-none focus:ring-2 focus:ring-secondary/50 outline-none transition-all"
                    placeholder="John Doe"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-700 ml-1">Phone</label>
                  <input
                    type="tel"
                    name="phone"
                    required
                    value={formData.phone}
                    onChange={handleChange}
                    className="w-full px-4 py-3 rounded-xl bg-slate-50 shadow-inner-3d border-none focus:ring-2 focus:ring-secondary/50 outline-none transition-all"
                    placeholder="+91..."
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-700 ml-1">Email</label>
                  <input
                    type="email"
                    name="email"
                    required
                    value={formData.email}
                    onChange={handleChange}
                    className="w-full px-4 py-3 rounded-xl bg-slate-50 shadow-inner-3d border-none focus:ring-2 focus:ring-secondary/50 outline-none transition-all"
                    placeholder="john@example.com"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-700 ml-1">Service</label>
                  <div className="relative">
                    <select
                        name="service"
                        value={formData.service}
                        onChange={handleChange}
                        className="w-full px-4 py-3 rounded-xl bg-slate-50 shadow-inner-3d border-none focus:ring-2 focus:ring-secondary/50 outline-none transition-all appearance-none"
                    >
                        <option>Digital Marketing</option>
                        <option>Web Development</option>
                        <option>Software Development</option>
                        <option>Business Automation</option>
                    </select>
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none">
                        <ChevronDown className="h-4 w-4 text-slate-400" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700 ml-1">Message</label>
                <textarea
                  name="message"
                  rows={4}
                  value={formData.message}
                  onChange={handleChange}
                  className="w-full px-4 py-3 rounded-xl bg-slate-50 shadow-inner-3d border-none focus:ring-2 focus:ring-secondary/50 outline-none transition-all resize-none"
                  placeholder="Tell us about your project..."
                ></textarea>
              </div>

              <motion.button 
                whileHover={{ scale: 1.02, translateY: -2 }}
                whileTap={{ scale: 0.98, translateY: 0 }}
                type="submit" 
                disabled={status === 'submitting'}
                className="w-full font-bold py-4 rounded-xl shadow-lg bg-brand-gradient text-white flex items-center justify-center gap-2 hover:shadow-indigo-500/30 transition-all"
              >
                {status === 'submitting' ? (
                  <>Sending... <Loader2 className="h-5 w-5 animate-spin" /></>
                ) : (
                  <>Send Message <Send className="h-5 w-5" /></>
                )}
              </motion.button>
            </form>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

