import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import gsap from 'gsap';
import { ArrowRight, Globe, ChevronsDown } from 'lucide-react';

const Hero: React.FC = () => {
  const mountRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // --- Three.js Setup ---
    if (!mountRef.current) return;

    const scene = new THREE.Scene();

    // Camera
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 2.5;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    mountRef.current.appendChild(renderer.domElement);

    // Particles Globe
    const particlesGeometry = new THREE.BufferGeometry();
    const particlesCount = 3000;

    const posArray = new Float32Array(particlesCount * 3);

    for(let i = 0; i < particlesCount * 3; i++) {
        // Create points on a sphere surface
        const phi = Math.acos(-1 + (2 * i) / particlesCount);
        const theta = Math.sqrt(particlesCount * Math.PI) * phi;

        const r = 1.2; // Radius

        posArray[i * 3] = r * Math.cos(theta) * Math.sin(phi);
        posArray[i * 3 + 1] = r * Math.sin(theta) * Math.sin(phi);
        posArray[i * 3 + 2] = r * Math.cos(phi);

        // Add some random noise
        posArray[i * 3] += (Math.random() - 0.5) * 0.05;
        posArray[i * 3 + 1] += (Math.random() - 0.5) * 0.05;
        posArray[i * 3 + 2] += (Math.random() - 0.5) * 0.05;
    }

    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));

    // Material
    const particlesMaterial = new THREE.PointsMaterial({
        size: 0.005,
        color: 0x38bdf8, // Light Blue
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending
    });

    const particlesMesh = new THREE.Points(particlesGeometry, particlesMaterial);
    scene.add(particlesMesh);

    // Add another layer of larger glowing particles
    const starGeometry = new THREE.BufferGeometry();
    const starCount = 100;
    const starPos = new Float32Array(starCount * 3);
    for(let i=0; i<starCount*3; i++) {
        starPos[i] = (Math.random() - 0.5) * 4;
    }
    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
    const starMaterial = new THREE.PointsMaterial({
        size: 0.02,
        color: 0xFACC15, // Yellow
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending
    });
    const starMesh = new THREE.Points(starGeometry, starMaterial);
    scene.add(starMesh);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0x38bdf8, 2);
    pointLight.position.set(2, 3, 4);
    scene.add(pointLight);

    // Animation
    let mouseX = 0;
    let mouseY = 0;

    const animate = () => {
      // Rotation
      particlesMesh.rotation.y += 0.001;
      particlesMesh.rotation.x += 0.0005;

      starMesh.rotation.y -= 0.0005;

      // Mouse interaction (smooth)
      particlesMesh.rotation.x += mouseY * 0.001;
      particlesMesh.rotation.y += mouseX * 0.001;

      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    };

    animate();

    // Event Listeners
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const handleMouseMove = (event: MouseEvent) => {
        mouseX = event.clientX / window.innerWidth - 0.5;
        mouseY = event.clientY / window.innerHeight - 0.5;
    };

    const handleScroll = () => {
        const scrollY = window.scrollY;
        // Smooth camera movement on scroll
        camera.position.y = -scrollY * 0.002;
        camera.position.z = 2.5 + scrollY * 0.001;
        particlesMesh.rotation.z = scrollY * 0.0005;
    };

    window.addEventListener('resize', handleResize);
    document.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('scroll', handleScroll);

    // --- GSAP Entrance Animations ---
    if (textRef.current) {
        const ctx = gsap.context(() => {
            gsap.from(".hero-text", {
                y: 50,
                opacity: 0,
                duration: 1.5,
                stagger: 0.2,
                ease: "power3.out",
                delay: 0.5
            });

            gsap.from(".hero-btn", {
                y: 20,
                opacity: 0,
                duration: 1,
                stagger: 0.1,
                ease: "back.out(1.7)",
                delay: 1.2
            });

            gsap.from(".scroll-indicator", {
                opacity: 0,
                y: -20,
                duration: 1,
                delay: 2,
                ease: "power2.out"
            });
        }, textRef);

        return () => {
            window.removeEventListener('resize', handleResize);
            document.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('scroll', handleScroll);
            if (mountRef.current) {
                mountRef.current.removeChild(renderer.domElement);
            }
            ctx.revert();
            // Dispose geometries and materials to avoid memory leaks
            particlesGeometry.dispose();
