import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const Scene3D: React.FC = () => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x050510, 0.02); // Dark blueish fog

    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.z = 4;

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.2);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0x38bdf8, 2); // Sky blue
    mainLight.position.set(5, 5, 5);
    scene.add(mainLight);

    const accentLight = new THREE.PointLight(0xFACC15, 2); // Yellow
    accentLight.position.set(-5, -5, 2);
    scene.add(accentLight);

    // --- Groups for different states ---
    const heroGroup = new THREE.Group();
    const webGroup = new THREE.Group();
    const softwareGroup = new THREE.Group();
    const automationGroup = new THREE.Group();

    scene.add(heroGroup);
    scene.add(webGroup);
    scene.add(softwareGroup);
    scene.add(automationGroup);

    // 1. HERO: Particle Globe
    const particleGeometry = new THREE.BufferGeometry();
    const pCount = 3000;
    const pPos = new Float32Array(pCount * 3);
    for(let i=0; i<pCount; i++) {
        const phi = Math.acos(-1 + (2 * i) / pCount);
        const theta = Math.sqrt(pCount * Math.PI) * phi;
        const r = 1.3;
        // Sphere coordinates with noise
        pPos[i*3] = r * Math.cos(theta) * Math.sin(phi) + (Math.random()-0.5)*0.1;
        pPos[i*3+1] = r * Math.sin(theta) * Math.sin(phi) + (Math.random()-0.5)*0.1;
        pPos[i*3+2] = r * Math.cos(phi) + (Math.random()-0.5)*0.1;
    }
    particleGeometry.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
    const particleMaterial = new THREE.PointsMaterial({
        size: 0.015,
        color: 0x38bdf8,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending
    });
    const globe = new THREE.Points(particleGeometry, particleMaterial);
    heroGroup.add(globe);

    // 2. WEB: Connected Network (Icosahedron Wireframe)
    const webGeo = new THREE.IcosahedronGeometry(1.2, 1);
    const webMat = new THREE.MeshBasicMaterial({ color: 0x38bdf8, wireframe: true, transparent: true, opacity: 0 });
    const webMesh = new THREE.Mesh(webGeo, webMat);
    webGroup.add(webMesh);

    // Add glowing nodes to web
    const webNodesGeo = new THREE.IcosahedronGeometry(1.2, 1);
    const webNodesMat = new THREE.PointsMaterial({ size: 0.05, color: 0xFACC15, transparent: true, opacity: 0 });
    const webNodes = new THREE.Points(webNodesGeo, webNodesMat);
    webGroup.add(webNodes);

    // 3. SOFTWARE: Floating Blocks (Matrix)
    const boxGeo = new THREE.BoxGeometry(0.3, 0.3, 0.3);
    const boxMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4, metalness: 0.8, transparent: true, opacity: 0 });
    for(let i=0; i<15; i++) {
        const mesh = new THREE.Mesh(boxGeo, boxMat);
        mesh.position.set(
            (Math.random()-0.5)*3,
            (Math.random()-0.5)*3,
            (Math.random()-0.5)*3
        );
        mesh.rotation.set(Math.random()*Math.PI, Math.random()*Math.PI, 0);
        softwareGroup.add(mesh);
    }

    // 4. AUTOMATION: Torus Knot (Gears/Machinery)
    const torusGeo = new THREE.TorusKnotGeometry(0.8, 0.1, 100, 16);
    const torusMat = new THREE.MeshStandardMaterial({ color: 0xFACC15, wireframe: false, roughness: 0.2, metalness: 1, transparent: true, opacity: 0 });
    const torus = new THREE.Mesh(torusGeo, torusMat);
    automationGroup.add(torus);

    // --- GLTF LOADER (Fallback implemented above, but logic for external models) ---
    // If you have models:
    // const loader = new GLTFLoader();
    // loader.load('path/to/web.glb', (gltf) => { webGroup.add(gltf.scene); });

    // --- SCROLL ANIMATIONS ---
    // We'll create a single timeline that maps the entire scroll height to scene transitions.
    const tl = gsap.timeline({
        scrollTrigger: {
            trigger: "body", // Track entire page
            start: "top top",
            end: "bottom bottom",
            scrub: 1.5, // smooth scrubbing
        }
    });

    // Initial State: Hero visible, others hidden
    webMesh.material.opacity = 0;
    webNodes.material.opacity = 0;

    // Phase 1: Hero -> Web (Scroll 0% -> 25%)
    tl.to(globe.rotation, { y: Math.PI, duration: 2 }, 0);
    tl.to(heroGroup.scale, { x: 0.1, y: 0.1, z: 0.1, duration: 2 }, 0);
    tl.to(particleMaterial, { opacity: 0, duration: 1 }, 0);

    tl.to(webMat, { opacity: 0.5, duration: 2 }, 1);
    tl.to(webNodesMat, { opacity: 0.8, duration: 2 }, 1);
    tl.fromTo(webGroup.rotation, { y: 0 }, { y: Math.PI, duration: 3 }, 0);

    // Phase 2: Web -> Software (Scroll 25% -> 50%)
    tl.to(webMat, { opacity: 0, duration: 2 }, 3);
    tl.to(webNodesMat, { opacity: 0, duration: 2 }, 3);

    tl.to(boxMat, { opacity: 1, duration: 2 }, 3.5);
    tl.fromTo(softwareGroup.rotation, { x: 0 }, { x: Math.PI, y: Math.PI, duration: 4 }, 3);

    // Phase 3: Software -> Automation (Scroll 50% -> 75%)
    tl.to(boxMat, { opacity: 0, duration: 2 }, 6);

    tl.to(torusMat, { opacity: 1, duration: 2 }, 6.5);
    tl.fromTo(automationGroup.rotation, { z: 0 }, { z: Math.PI * 2, duration: 4 }, 6);

    // Phase 4: Final Scale Out (Scroll 75% -> 100%)
    tl.to(torus.scale, { x: 1.5, y: 1.5, z: 1.5, duration: 3 }, 9);

    // --- ANIMATION LOOP ---
    const clock = new THREE.Clock();
    const animate = () => {
        const time = clock.getElapsedTime();

        // Constant idle animations
        globe.rotation.y += 0.001;
        webGroup.rotation.z = Math.sin(time * 0.1) * 0.1;
        softwareGroup.children.forEach((child, i) => {
             child.rotation.x += 0.005;
             child.position.y += Math.sin(time + i) * 0.002;
        });
        torus.rotation.x += 0.005;

        renderer.render(scene, camera);
        requestAnimationFrame(animate);
    };
    animate();

    const handleResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', handleResize);

    return () => {
        window.removeEventListener('resize', handleResize);
        ScrollTrigger.getAll().forEach(t => t.kill());
        if (mountRef.current && renderer.domElement) {
            mountRef.current.removeChild(renderer.domElement);
        }
        renderer.dispose();
    };
  }, []);

  return (
    <div 
        ref={mountRef} 
        className="fixed inset-0 z-0 pointer-events-none bg-gradient-to-b from-slate-900 via-[#0a0f1e] to-black"
    />
  );
};

export default Scene3D;

