import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { ArrowRight, Globe, ChevronsDown } from 'lucide-react';

const Hero: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let particles: Particle[] = [];
    let animationFrameId: number;

    const mouse = {
      x: null as number | null,
      y: null as number | null,
      radius: 150
    };

    class Particle {
      x: number;
      y: number;
      directionX: number;
      directionY: number;
      size: number;
      color: string;

      constructor(x: number, y: number, directionX: number, directionY: number, size: number, color: string) {
        this.x = x;
        this.y = y;
        this.directionX = directionX;
        this.directionY = directionY;
        this.size = size;
        this.color = color;
      }

      draw() {
        if (!ctx) return;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2, false);
        ctx.fillStyle = this.color;
        ctx.fill();
      }

      update() {
        if (this.x > canvas!.width || this.x < 0) {
          this.directionX = -this.directionX;
        }
        if (this.y > canvas!.height || this.y < 0) {
          this.directionY = -this.directionY;
        }

        // Mouse interaction
        let dx = (mouse.x || 0) - this.x;
        let dy = (mouse.y || 0) - this.y;
        let distance = Math.sqrt(dx * dx + dy * dy);

        if (mouse.x !== null && distance < mouse.radius) {
          if (mouse.x < this.x && this.x < canvas!.width - this.size * 10) {
            this.x += 3;
          }
          if (mouse.x > this.x && this.x > this.size * 10) {
            this.x -= 3;
          }
          if (mouse.y < this.y && this.y < canvas!.height - this.size * 10) {
            this.y += 3;
          }
          if (mouse.y > this.y && this.y > this.size * 10) {
            this.y -= 3;
          }
        }

        this.x += this.directionX;
        this.y += this.directionY;
        this.draw();
      }
    }

    const init = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      particles = [];
      const numberOfParticles = (canvas.width * canvas.height) / 9000;

      for (let i = 0; i < numberOfParticles; i++) {
        const size = (Math.random() * 2) + 1;
        const x = (Math.random() * ((canvas.width - size * 2) - (size * 2)) + size * 2);
        const y = (Math.random() * ((canvas.height - size * 2) - (size * 2)) + size * 2);
        const directionX = (Math.random() * 2) - 1; 
        const directionY = (Math.random() * 2) - 1;
        const color = '#38bdf8'; // Light Blue

        particles.push(new Particle(x, y, directionX * 0.4, directionY * 0.4, size, color));
      }
    };

    const connect = () => {
      let opacityValue = 1;
      for (let a = 0; a < particles.length; a++) {
        for (let b = a; b < particles.length; b++) {
          let distance = ((particles[a].x - particles[b].x) * (particles[a].x - particles[b].x)) + 
                         ((particles[a].y - particles[b].y) * (particles[a].y - particles[b].y));

          if (distance < (canvas!.width / 7) * (canvas!.height / 7)) {
            opacityValue = 1 - (distance / 20000);
            if (opacityValue > 0) {
              ctx.strokeStyle = `rgba(56, 189, 248, ${opacityValue * 0.2})`; // Blue lines
              ctx.lineWidth = 1;
              ctx.beginPath();
              ctx.moveTo(particles[a].x, particles[a].y);
              ctx.lineTo(particles[b].x, particles[b].y);
              ctx.stroke();
            }
          }
        }
      }
    };

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);
      if (!ctx || !canvas) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (let i = 0; i < particles.length; i++) {
        particles[i].update();
      }
      connect();
    };

    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      init();
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.x;
      mouse.y = e.y;
    };

    const handleMouseOut = () => {
      mouse.x = null;
      mouse.y = null;
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseout', handleMouseOut);

    init();
    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseout', handleMouseOut);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  const handleSmoothScroll = (e: React.MouseEvent<HTMLAnchorElement>, targetId: string) => {
    e.preventDefault();
    const element = document.getElementById(targetId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section id="home" className="relative w-full h-screen overflow-hidden bg-gradient-to-b from-slate-900 via-[#0a0f1e] to-black">

      <style>{`
        @keyframes tiranga-flow {
          0% { background-position: 0% 50%; }
          100% { background-position: 200% 50%; }
        }
        .tiranga-text {
          background: linear-gradient(90deg, #FF9933, #FFFFFF, #138808, #FF9933);
          background-size: 200% auto;
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          animation: tiranga-flow 3s linear infinite;
        }
      `}</style>

      {/* 2D Network Canvas */}
      <canvas 
        ref={canvasRef} 
        className="absolute inset-0 z-0 w-full h-full opacity-60"
      />

      {/* Overlay Content */}
      <div className="relative z-10 w-full max-w-7xl mx-auto px-6 h-full flex items-center pointer-events-none">
        <div className="grid grid-cols-1 lg:grid-cols-12 w-full">
            <div className="lg:col-span-8 text-left pointer-events-auto">
                <motion.h1 
                  initial={{ opacity: 0, y: 30 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.8, ease: "easeOut" }}
                  className="text-5xl sm:text-6xl md:text-8xl font-bold leading-[1.1] mb-8 text-white tracking-tight font-heading"
                >
                    <span className="block text-slate-200">
                        Empowering
                    </span>
                    <span className="block tiranga-text drop-shadow-[0_0_30px_rgba(255,255,255,0.2)]">
                        India
                    </span>
                    <span className="block text-3xl sm:text-4xl md:text-6xl mt-4 text-slate-300 font-normal">
                        with Digital & Automation Solutions.
                    </span>
                </motion.h1>

                <motion.p 
                  initial={{ opacity: 0, y: 30 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.8, delay: 0.2, ease: "easeOut" }}
                  className="text-lg sm:text-xl text-slate-400 mb-10 max-w-2xl leading-relaxed font-light"
                >
                    From result-driven marketing to smart business automation — we build the technology that helps your business grow in the digital era.
                </motion.p>

                <motion.div 
                   initial={{ opacity: 0, y: 20 }}
                   animate={{ opacity: 1, y: 0 }}
                   transition={{ duration: 0.8, delay: 0.4, ease: "easeOut" }}
                   className="flex flex-col sm:flex-row gap-5"
                >
                    <a 
                    href="#contact" 
                    onClick={(e) => handleSmoothScroll(e, 'contact')}
                    className="group relative px-8 py-4 rounded-xl bg-primary text-black font-bold text-lg hover:shadow-[0_0_25px_rgba(250,204,21,0.5)] transition-all transform hover:-translate-y-1 w-full sm:w-auto text-center flex items-center justify-center gap-3 overflow-hidden"
                    >
                        <span className="relative z-10">Start Project</span>
                        <ArrowRight className="w-5 h-5 relative z-10 group-hover:translate-x-1 transition-transform" />
                        <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-20 transition-opacity duration-300"></div>
                    </a>

                    <a 
                    href="#services" 
                    onClick={(e) => handleSmoothScroll(e, 'services')}
                    className="group px-8 py-4 rounded-xl glass-card text-white font-bold text-lg hover:bg-white/10 transition-all border border-white/10 hover:border-primary/50 backdrop-blur-md w-full sm:w-auto text-center flex items-center justify-center gap-3"
                    >
                        <Globe className="w-5 h-5 text-primary group-hover:rotate-12 transition-transform" />
                        <span>Explore Solutions</span>
                    </a>
                </motion.div>
            </div>
        </div>
      </div>

      {/* Scroll indicator */}
      <motion.div 
         initial={{ opacity: 0 }}
         animate={{ opacity: 1 }}
         transition={{ delay: 1, duration: 1 }}
         className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20"
      >
          <a
            href="#about"
            onClick={(e) => handleSmoothScroll(e, 'about')}
            className="flex flex-col items-center gap-2 cursor-pointer group p-2"
          >
            <span className="text-[10px] uppercase tracking-[0.2em] text-slate-500 group-hover:text-primary transition-colors duration-300">Scroll</span>
            <div className="animate-bounce">
               <ChevronsDown className="w-8 h-8 text-slate-500 group-hover:text-primary transition-colors duration-300 opacity-80" />
            </div>
          </a>
      </motion.div>
    </section>
  );
};

