                    className="w-full px-4 py-3 rounded-lg glass-input placeholder:text-slate-600 resize-none focus:border-primary focus:shadow-[0_0_15px_rgba(255,153,51,0.2)]"
                    placeholder="How can we help you?"
                  ></textarea>
                </div>

                <motion.button 
                  whileHover={{ scale: 1.01 }}
                  whileTap={{ scale: 0.99 }}
                  type="submit" 
                  disabled={status === 'submitting'}
                  className="w-full font-bold py-4 rounded-lg bg-primary text-black flex items-center justify-center gap-2 hover:shadow-glow hover:bg-white transition-all"
                >
                  {status === 'submitting' ? (
                    <>Sending... <Loader2 className="h-5 w-5 animate-spin" /></>
                  ) : (
                    <>Send Request <ArrowRight className="h-5 w-5" /></>
                  )}
                </motion.button>
              </form>
            </div>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

