import React, { useRef, useEffect } from "react";
import { motion, useInView, useAnimation } from "framer-motion";

interface Props {
  children: React.ReactNode;
  width?: "fit-content" | "100%";
  className?: string;
  delay?: number;
}

export const RevealOnScroll: React.FC<Props> = ({ children, width = "100%", className="", delay=0 }) => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-10%" });
  const controls = useAnimation();

  useEffect(() => {
    if (isInView) {
      controls.start("visible");
    }
  }, [isInView, controls]);

  return (
    <div ref={ref} style={{ width }} className={className}>
      <motion.div
        variants={{
          hidden: { opacity: 0, y: 50, rotateX: 15, scale: 0.9, filter: "blur(10px)" },
          visible: { opacity: 1, y: 0, rotateX: 0, scale: 1, filter: "blur(0px)" },
        }}
        initial="hidden"
        animate={controls}
        transition={{ duration: 1.0, delay: delay, ease: [0.22, 1, 0.36, 1] }} // Custom cubic bezier for smooth "ease-out"
        style={{ transformStyle: "preserve-3d", perspective: "1000px" }}
      >
        {children}
      </motion.div>
    </div>
  );
};

