// Parallax Camera Rig
const Rig = () => {
  const { camera, mouse } = useThree();
  const vec = new THREE.Vector3();

  useFrame(() => {
    // Soft mouse parallax
    camera.position.lerp(vec.set(mouse.x * 2, mouse.y * 1, 12), 0.05);
    camera.lookAt(0, 0, 0);
  });
  return null;
};

