'use client';
import React, { useState, useEffect } from 'react';
import { ArrowUp } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const BackToTop: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const toggleVisibility = () => {
      if (window.scrollY > 300) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.button
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 20 }}
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          onClick={scrollToTop}
          className="fixed bottom-8 right-8 z-50 p-3 bg-primary text-white rounded-full shadow-lg hover:shadow-xl hover:bg-primary-dark transition-all"
          aria-label="Scroll to top"
        >
          <ArrowUp className="h-6 w-6" />
        </motion.button>
      )}
    </AnimatePresence>
  );
};

export default BackToTop;

import React, { useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import { 
  ArrowRight, 
  MapPin, 
  Search, 
  Code2, 
  BarChart3, 
  Globe, 
  Megaphone, 
  MousePointer2 
} from 'lucide-react';

const Hero: React.FC = () => {
  const ref = useRef<HTMLDivElement>(null);

  // Track scroll progress for parallax effects
  const { scrollY } = useScroll();

  // Parallax Transforms: Different layers move at different speeds
  // Background blobs move down slowly
  const yBlobs = useTransform(scrollY, [0, 1000], [0, 400]);

  // Rings rotate and move upward to create counter-movement
  const rotateRings = useTransform(scrollY, [0, 1000], [0, 90]);
  const yRings = useTransform(scrollY, [0, 1000], [0, -150]);

  // Floating icons move faster (foreground effect)
  const yIcons = useTransform(scrollY, [0, 1000], [0, -300]);

  // Main content moves slightly to create separation from background
  const yContent = useTransform(scrollY, [0, 1000], [0, 100]);
  const opacityContent = useTransform(scrollY, [0, 600], [1, 0]);

  const handleSmoothScroll = (e: React.MouseEvent<HTMLAnchorElement>, targetId: string) => {
    e.preventDefault();
