      </motion.div>

      {/* Rotating Tech Rings - Parallax Layer 2 (Mid) */}
      <motion.div 
        style={{ y: yRings, rotate: rotateRings }} 
        className="absolute inset-0 z-0 flex items-center justify-center pointer-events-none opacity-60"
      >
        <motion.div 
          className="absolute w-[300px] md:w-[800px] h-[300px] md:h-[800px] rounded-full border border-white/5 border-dashed"
          animate={{ rotate: 360 }}
          transition={{ duration: 120, repeat: Infinity, ease: "linear" }}
        />
        <motion.div 
          className="absolute w-[220px] md:w-[600px] h-[220px] md:h-[600px] rounded-full border border-white/10 border-dashed"
          animate={{ rotate: -360 }}
          transition={{ duration: 60, repeat: Infinity, ease: "linear" }}
        />
         <motion.div 
          className="absolute w-[150px] md:w-[300px] h-[150px] md:h-[300px] rounded-full border border-white/5 border-dotted"
          animate={{ rotate: 180 }}
          transition={{ duration: 40, repeat: Infinity, ease: "linear" }}
